<section class="admin-welcome"><div><h1>Coupons promotionnels</h1><p>Créez des remises limitées et mesurables.</p></div></section>
<form class="panel admin-editor" method="post" action="/admin/coupons"><section class="editor-section"><div class="field-grid"><label>Code *<input name="code" required placeholder="BIENVENUE10"></label><label>Type<select name="type"><option value="percent">Pourcentage</option><option value="fixed">Montant fixe</option></select></label><label>Valeur *<input type="number" min="0" step="0.01" name="value" required></label><label>Minimum d’achat<input type="number" min="0" name="minimum_amount" value="0"></label><label>Nombre maximal d’utilisations<input type="number" min="1" name="usage_limit" placeholder="Illimité"></label><label>Début<input type="datetime-local" name="starts_at"></label><label>Expiration<input type="datetime-local" name="expires_at"></label></div></section><footer><button class="btn primary">Créer / réactiver le coupon</button></footer></form>
<section class="panel table-panel"><div class="table-responsive"><table><thead><tr><th>CODE</th><th>REMISE</th><th>UTILISATIONS</th><th>VALIDITÉ</th><th>STATUT</th><th></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><strong><?= htmlspecialchars($item['code']) ?></strong></td><td><?= number_format($item['value'],0,',',' ') ?><?= $item['type']==='percent'?' %':' F' ?></td><td><?= (int)$item['used_count'] ?> / <?= $item['usage_limit']===null?'∞':(int)$item['usage_limit'] ?></td><td><?= $item['expires_at']?date('d/m/Y',strtotime($item['expires_at'])):'Sans expiration' ?></td><td><span class="status <?= $item['status']==='active'?'published':'draft' ?>"><?= htmlspecialchars($item['status']) ?></span></td><td><?php if($item['status']==='active'): ?><form method="post" action="/admin/coupons/supprimer"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn secondary">Désactiver</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section>
